#include <iostream>
#include <climits>

int main() {
    int a = 0;
    int b = 0;

    if (std::cin >> a >> b) {
        // Check whether a + b would overflow according to CERT INT32-CPP
        if ((b > 0 && a > INT_MAX - b) || (b < 0 && a < INT_MIN - b)) {
            std::cout << "Overflow detected!\n";
        } else {
            int sum = a + b;
            std::cout << "Sum: " << sum << "\n";
        }
    } else {
        std::cout << "Invalid input format.\n";
    }

    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    int total = 0;
    int counter = 0;
    int grade = 0;

    // Sentinel-controlled loop processing grades until -1 is entered
    while (std::cin >> grade && grade != -1) {
        total += grade;
        ++counter;
    }

    // Termination phase: protect against division by zero
    if (counter != 0) {
        double average = static_cast<double>(total) / counter;
        std::cout << "Total of all " << counter << " grades is " << total << "\n";
        std::cout << std::fixed << std::setprecision(2);
        std::cout << "Class average is " << average << "\n";
    } else {
        std::cout << "No grades were entered\n";
    }

    return 0;
}
